function remove(r: ReproductionRecord, type: string) {
  const i = r.events.findIndex((e) => e.type === type);
  expect(i).toBeGreaterThanOrEqual(0);
  r.events.splice(i, 1);
  for (const cp of r.checkpoints) if (cp.eventCount > i) cp.eventCount--;
}
